{
  "name": "@renjfk/opencode-secret-tools",
  "version": "1.0.0",
  "description": "Configurable secret bridge for OpenCode. Provides list_secrets, get_secret, and clear_secret tools that shell out to any CLI-based secret store with automatic redaction.",
  "keywords": [
    "opencode",
    "plugin",
    "redaction",
    "secret",
    "vault"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/renjfk/opencode-secret-tools.git"
  },
  "files": [
    "index.js",
    "lib",
    "screenshots"
  ],
  "type": "module",
  "main": "index.js",
  "exports": {
    ".": {
      "import": "./index.js"
    }
  },
  "scripts": {
    "lint": "npx oxlint .",
    "fmt": "npx oxfmt --check .",
    "fmt:fix": "npx oxfmt --write .",
    "test": "node --test",
    "check": "npm run lint && npm run fmt",
    "prepack": "npm run check"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.1",
    "oxfmt": "0.50.0",
    "oxlint": "1.65.0"
  }
}
